package com.classvoice.controller; import com.classvoice.dao.*; import com.classvoice.model.User; import com.classvoice.util.WebUtil; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import jakarta.servlet.*; import java.io.IOException;
@WebServlet("/teacher/analysis") public class FeedbackAnalysisServlet extends HttpServlet {protected void doGet(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{try{User u=(User)r.getSession().getAttribute("user");long id=WebUtil.longParam(r,"lectureId");LectureDAO ld=new LectureDAO();if(id<1||!ld.belongsToTeacher(id,u.getUserId())){p.sendError(404);return;}r.setAttribute("lecture",ld.findById(id));r.setAttribute("stats",new FeedbackDAO().stats(id));r.setAttribute("feedbackList",new FeedbackDAO().findByLecture(id));r.getRequestDispatcher("/WEB-INF/views/feedback-analysis.jsp").forward(r,p);}catch(Exception e){throw new ServletException(e);}}}
